syntax:
object OffsetPage {
  val FullSetMax: Int = 500
  def header(p: OffsetPage, noun: String): String = if (p.isAll) s"### ${
    math.max(p.total, p.shown)
  } $noun" else s"### ${
    p.shown
  } of ${
    p.total
  } $noun"
  def footer(p: OffsetPage): String = if (p.isAll || p.shown == 0) "" else {
    val next = p.next.fold("")(n => s" — next: offset=$n")
    val full = if (p.total <= FullSetMax) s" — full set: limit=${
      p.total
    }" else ""
    s"

_showing ${
      p.offset + 1
    }–${
      p.offset + p.shown
    } of ${
      p.total
    }$next${
      full
    }_"
  }
  def markdown[A](p: OffsetPage, noun: String, empty: String, items: List[A])(line: A => String): String = if (items.isEmpty) p.offset match {
    case 0 =>
      empty
    case o =>
      s"$empty

_offset=$o is past the end: there are ${
        p.total
      }_"
  } else s"${
    header(p, noun)
  }

${
    items.map(line).mkString("
")
  }${
    footer(p)
  }"
}

def header(p: OffsetPage, noun: String): String = if (p.isAll) s"### ${
  math.max(p.total, p.shown)
} $noun" else s"### ${
  p.shown
} of ${
  p.total
} $noun"

