syntax:
def footer(p: OffsetPage): String = if (p.isAll || p.shown == 0) "" else {
  val next = p.next.fold("")(n => s" — next: offset=$n")
  val full = if (p.total <= FullSetMax) s" — full set: limit=${
    p.total
  }" else ""
  s"

_showing ${
    p.offset + 1
  }–${
    p.offset + p.shown
  } of ${
    p.total
  }$next${
    full
  }_"
}

def markdown[A](p: OffsetPage, noun: String, empty: String, items: List[A])(line: A => String): String = if (items.isEmpty) p.offset match {
  case 0 =>
    empty
  case o =>
    s"$empty

_offset=$o is past the end: there are ${
      p.total
    }_"
} else s"${
  header(p, noun)
}

${
  items.map(line).mkString("
")
}${
  footer(p)
}"

s"$empty

_offset=$o is past the end: there are ${
  p.total
}_"

final case class OffsetPage(total: Int, offset: Int, shown: Int) {
  def next: Option[Int] = Option.when(shown > 0 && offset + shown < total)(offset + shown)
  def isAll: Boolean = offset == 0 && shown >= total
}

final case class Filter(q: Option[String] = None, tags: List[String] = Nil, authors: List[String] = Nil, places: List[String] = Nil, topics: List[String] = Nil, status: List[String] = Nil, years: Option[Period] = None, period: Option[Period] = None, bbox: Option[BBox] = None, sort: Sort = Sort.Relevance, limit: Int = 0, offset: Int = 0, title: Option[String] = None, goal: Option[String] = None) derives KindlingsCodecAsObject, KindlingsSchema, com.histmersion.api.json.Schema {
  def isEmpty: Boolean = q.forall(_.trim.isEmpty) && tags.isEmpty && authors.isEmpty && places.isEmpty && topics.isEmpty && status.isEmpty && years.isEmpty && period.isEmpty && bbox.isEmpty && title.forall(_.trim.isEmpty) && goal.forall(_.trim.isEmpty)
  def sourceSet: Filter = Filter(q, tags, authors, places, topics, status, years, period, bbox, goal = goal)
  def hasFindingCriteria: Boolean = period.isDefined || bbox.isDefined || places.nonEmpty || tags.nonEmpty
}

