syntax:
result.hits.map { hit =>
  val h = hit.source
  val reg = h.regions.map(Label.display).mkString(", ")
  val meta = List(year(h.year), h.status.wire, reg).filter(_.nonEmpty).mkString(" · ")
  val per = period(h.periodStart, h.periodEnd)
  val metaLine = if (per.nonEmpty) s"$meta · $per" else meta
  val why = if (hit.why.isEmpty) "" else s"
  why: ${
    hit.why.mkString(" · ")
  }"
  val summary = h.summary.map(s => s"
  ${
    s.trim.take(240)
  }").getOrElse("")
  val matched = if (hit.matched.isEmpty) "" else {
    val items = hit.matched.map { m =>
      val loc = place(m.regionName, m.lat, m.lon)
      val p = period(m.periodStart, m.periodEnd)
      val tail = List(loc, p, m.why.mkString(", ")).filter(_.nonEmpty).mkString(" · ")
      s"
    - ${
        m.claim.trim
      }${
        if (tail.nonEmpty) s"  
      _${
          tail
        }_" else ""
      }"
    }
    s"
  matches:${
      items.mkString
    }"
  }
  s"- **${
    h.citekey
  }** — ${
    h.title
  }
  _${
    metaLine
  }_$why${
    snippet(h)
  }$summary$matched"
}

