syntax:
result.hits.map { hit =>
  val h = hit.source
  val per = period(h.periodStart, h.periodEnd)
  val meta = List(year(h.year), h.status.wire, per).filter(_.nonEmpty).mkString(" · ")
  val why = hit.why.headOption.map(w => s" — $w").getOrElse("")
  s"- **${
    h.citekey
  }** — ${
    h.title
  }  
  _${
    meta
  }_$why"
}

