f.places.foreach { p =>
  val byGazetteer = scope.idsFor(p).exists(ids => placeIds.exists(ids.contains))
  if (byGazetteer || m.regionName.exists(_.toLowerCase.contains(p.toLowerCase))) b += (s"place: ${
    scope.labelFor(p)
  }")
}

