syntax:
def sources(filter: Filter, snippetWords: Int, scope: PlaceScope = PlaceScope.empty)(using DbCon): SearchResult = {
  val total = FilterSql.countQuery(filter, scope).frag.query[Int].run().headOption.getOrElse(0)
  val rows = FilterSql.sourcesQuery(filter, snippetWords, scope).frag.query[FilterSql.SourceRow].run()
  if (rows.isEmpty) SearchResult.of(total, Nil, filter.offset.max(0)) else {
    val citekeys = rows.map(_.citekey).toList
    val snippets: Map[String, FilterSql.SnippetRow] = FilterSql.text(filter) match {
      case Some(q) =>
        FilterSql.snippetsQuery(q, snippetWords, citekeys).frag.query[FilterSql.SnippetRow].run().map(s => s.citekey -> s).toMap
      case None =>
        Map.empty
    }
    val byCk = FilterSql.findingsQuery(citekeys).frag.query[FindingHitRow].run().groupBy(_.citekey)
    val hits = rows.map { r =>
      val withSnippet = snippets.get(r.citekey) match {
        case Some(sr) =>
          r.modify(_.snippet).setTo(Some(sr.snippet)).modify(_.matchedHeading).setTo(sr.heading)
        case None =>
          r
      }
      val matched = if (!filter.hasFindingCriteria) Nil else byCk.getOrElse(r.citekey, Vector.empty).toList.flatMap { fr =>
        val m = fr.toMatch
        val why = FilterSql.findingWhy(filter, m, fr.assignedPlaceIds, scope)
        if (why.isEmpty) None else Some(m.modify(_.why).setTo(why))
      }
      Hit(withSnippet.toHit, matched, FilterSql.sourceWhy(filter, withSnippet))
    }
    SearchResult.of(total, hits.toList, filter.offset.max(0))
  }
}

rows.map { r =>
  val withSnippet = snippets.get(r.citekey) match {
    case Some(sr) =>
      r.modify(_.snippet).setTo(Some(sr.snippet)).modify(_.matchedHeading).setTo(sr.heading)
    case None =>
      r
  }
  val matched = if (!filter.hasFindingCriteria) Nil else byCk.getOrElse(r.citekey, Vector.empty).toList.flatMap { fr =>
    val m = fr.toMatch
    val why = FilterSql.findingWhy(filter, m, fr.assignedPlaceIds, scope)
    if (why.isEmpty) None else Some(m.modify(_.why).setTo(why))
  }
  Hit(withSnippet.toHit, matched, FilterSql.sourceWhy(filter, withSnippet))
}

