syntax:
def toFilter: Filter = {
  val effectiveFrom = from.orElse(periodStart)
  val effectiveTo = to.orElse(periodEnd)
  val effectivePlaces = places ++ region.map(_.trim).filter(_.nonEmpty).toList
  Filter.of(query, tags, authors, effectivePlaces, topics, status, yearFrom, yearTo, effectiveFrom, effectiveTo, minLon, minLat, maxLon, maxLat, sort, limit, None)
}

