syntax:
def toFilter(except: Set[String] = Set.empty): Filter = {
  def keep(keys: String*) = !keys.exists(except)
  val box = if (keep("bbox") && inView.now()) bbox.now().flatMap(parseBbox) else None
  val f = Filter.of(q = if (keep("q")) q.now() else None, tags = if (keep("tags", "tag")) withPreview("tags", tags.now()) else Nil, authors = if (keep("authors", "author")) withPreview("authors", authors.now()) else Nil, places = (if (keep("places", "place")) withPreview("places", places.now()) else Nil) ++ (if (keep("placeIds", "place")) placeIds.now() else Nil), topics = if (keep("topics", "topic")) withPreview("topics", topics.now()) else Nil, status = if (keep("status")) withPreview("status", status.now()) else Nil, yearFrom = if (keep("yearFrom")) yearFrom.now() else None, yearTo = if (keep("yearTo")) yearTo.now() else None, from = if (keep("from")) from.now() else None, to = if (keep("to")) to.now() else None, minLon = box.map(_._1), minLat = box.map(_._2), maxLon = box.map(_._3), maxLat = box.map(_._4), sort = sort.now(), limit = None, offset = None, title = if (keep("title")) title.now() else None, goal = if (keep("goal")) goal.now() else None)
  val p = f.period
  val corrected = if (p.exists(pp => pp.start > pp.end)) f.modify(_.period).setTo(p.map(pp => Period(pp.end, pp.start))) else f
  val y = corrected.years
  if (y.exists(yy => yy.start > yy.end)) corrected.modify(_.years).setTo(y.map(yy => Period(yy.end, yy.start))) else corrected
}

